using System.ComponentModel;

namespace ElegantSeries.Flow.Routing;

/// <summary>
/// Marks an assembly as containing view registrations generated by the
/// ElegantSeries.Flow source generator (a <c>ViewForRegistrations</c> class
/// in the assembly's <c>&lt;assembly name&gt;.FlowGenerated</c> namespace, or in the
/// fallback <c>ElegantSeries.Flow.Generated</c> namespace when the assembly
/// has no name).
/// </summary>
/// <remarks>
/// <para>
/// This attribute is emitted by the source generator into the generated
/// registrations file; it is never written by hand. Its presence is how the
/// generator, when compiling an assembly that references this one,
/// recognizes the referenced assembly as a view-registration provider and
/// includes it in the <c>RegisterAllAttributedViews</c> aggregation.
/// </para>
/// <para>
/// The attribute carries no data and has no runtime effect; it is a
/// compile-time marker only.
/// </para>
/// </remarks>
[AttributeUsage(AttributeTargets.Assembly, AllowMultiple = false, Inherited = false)]
[EditorBrowsable(EditorBrowsableState.Never)]
public sealed class GeneratedViewRegistrationsAttribute : Attribute
{
}
